INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", "", "", "", "", "", "", 302, 91, 13020011, 13020014);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", "", "いかんいかん\n資材の山に埋もれて\nしまうところだった", 10, "", "", "", 302, 11, 111031, 13020015);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", "", "", "", "", "", "", 302, 91, 0, 13020016);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (0.2, "", "nyx_302_yuni_02", 0, 1, "NoItem", "", 302, 3, 2, 13020017);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (0.2, "", "nyx_302_yuni_02", 0, 1, "nyx_idle_normal", 0.2, 302, 3, 111031, 13020018);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", "", "だが怪我の功名、\n探していた部品を\n偶然にも発見できた", 10, "", "", "", 302, 11, 111031, 13020019);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", "", "", "", "", "", "", 302, 93, 5, 13020020);
