INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (0.2, "", "nyx_cmn_03", 1, "", "", "", 302, 3, 111031, 13020022);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", "", "ふむ…これは僥倖\nかくなる上は再び\n潜航してみるか…", 10, "", "", "", 302, 11, 111031, 13020023);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", "", "", "", "", "", "", 302, 91, 0, 13020024);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (0.2, "", "nyx_301_yuni_01", 1, "", "", "", 302, 3, 111031, 13020025);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", "", "存外意義あるものだ\n資材ダイビングとか\nいう新種の探索行は", 10, "", "", "", 302, 11, 111031, 13020026);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", "", 1, "", "", "", "", 302, 91, 0, 13020027);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", "", "まあ万一溺れたとて\n後輩たちの誰ぞが\nきっと気付くだろう", 10, "", "", "", 302, 11, 111031, 13020028);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", "", 1, "", "", "", "", 302, 91, 0, 13020029);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (0.2, "", "nyx_302_yuni_03", 0, 1, "nyx_302_yuni_04", "", 302, 3, 111031, 13020030);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", "", "是非もなし\nいざ往かん！", 10, "", "", "", 302, 11, 111031, 13020031);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", "", 1, "", "", "", "", 302, 91, 0, 13020032);
